function validate([variables, target]) {
  if (!Array.isArray(variables) || variables.length < 1 || variables.length > 100) return 'variables needs 1 to 100 entries.';
  for (const entry of variables) {
    if (!Array.isArray(entry) || entry.length !== 4) return 'Each entry is [a, b, c, m].';
    if (entry.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'a, b, c and m are between 1 and 1000.';
  }
  if (!Number.isInteger(target) || target < 0 || target > 1000) return 'target is between 0 and 1000.';
  return null;
}

