function getGoodIndices(variables, target) {
  function power(base, exponent, mod) {
    let result = 1 % mod;
    base %= mod;
    while (exponent > 0) {
      if (exponent % 2 === 1) {
        result = (result * base) % mod;
      }
      base = (base * base) % mod;
      exponent = Math.floor(exponent / 2);
    }
    return result;
  }

  const good = [];
  for (let i = 0; i < variables.length; i++) {
    const [a, b, c, m] = variables[i];
    const lastDigit = power(a, b, 10);
    if (power(lastDigit, c, m) === target) {
      good.push(i);
    }
  }
  return good;
}

