function getGoodIndices(variables, target) {
  const result = [];
  variables.forEach(([a, b, c, m], index) => {
    const digit = (BigInt(a) ** BigInt(b)) % 10n;
    const value = (digit ** BigInt(c)) % BigInt(m);
    if (value === BigInt(target)) result.push(index);
  });
  return result;
}

