function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const count = large ? 100 : pick(1, 6);
  const top = large ? 1000 : 25;
  const variables = Array.from({ length: count }, () => {
    const m = rand() < 0.5 ? pick(1, 12) : pick(1, top);
    return [pick(1, top), pick(1, large ? 1000 : 8), pick(1, large ? 1000 : 8), m];
  });
  // Aim the target at a real value most of the time so good indices appear.
  let target;
  if (rand() < 0.75) {
    const [a, b, c, m] = variables[pick(0, count - 1)];
    let digit = 1;
    for (let k = 0; k < b; k++) digit = (digit * a) % 10;
    let value = 1 % m;
    for (let k = 0; k < c; k++) value = (value * digit) % m;
    target = value;
  } else {
    target = pick(0, large ? 1000 : 12);
  }
  return [variables, target];
}
